def compute(vars):
    shares_outstanding = vars["Shares Outstanding"]
    share_price = vars["Share Price"]
    market_capitalization = shares_outstanding * share_price
    return {
        "value": market_capitalization,
        "trace": {
            "Shares Outstanding": shares_outstanding,
            "Share Price": share_price,
            "output_meta": {
                "currency": "$",
                "scale": None,
                "unit": "$"
            }
        }
    }
